import { cn } from 'cn';
import {
  BaseListPlugin,
  type Editor,
  type Element,
  isOrderedList,
  ListType,
} from 'platejs';
import { BaseDetailsPlugin } from 'platejs/details';
import { BaseImagePlugin } from 'platejs/media';
import type { RenderStaticNodeWrapper } from 'platejs/static';
import * as React from 'react';

type ListWrapper = RenderStaticNodeWrapper<typeof BaseListPlugin>;

// Toggles and images draw no wrapped children, so their bullets keep the
// marker on the block itself.
export const drawsBulletOnRoot = (editor: Editor, element: Element) =>
  element.listType === ListType.Bulleted &&
  !isOrderedList(element) &&
  [BaseDetailsPlugin, BaseImagePlugin].some((descriptor) => {
    const plugin = editor.plugin(descriptor);

    return plugin.installed && element.type === plugin.schema.type;
  });

export const BlockListStatic: ListWrapper = (props) => {
  const { listStyle, listType } = props.element;

  if (!listType || drawsBulletOnRoot(props.editor, props.element)) {
    return undefined;
  }

  return function BlockListStaticWrapper(innerProps) {
    return (
      <List
        {...innerProps}
        listStart={
          listType === ListType.Numbered
            ? innerProps.editor
                .plugin(BaseListPlugin)
                .read.ordinal(innerProps.path)
            : undefined
        }
        listStyle={listStyle}
        listType={listType}
      />
    );
  };
};

function List(
  props: Parameters<NonNullable<ReturnType<ListWrapper>>>[0] & {
    listStart?: number;
    listStyle?: string;
    listType: ListType;
  }
) {
  const { listStart, listStyle, listType } = props;
  const isTask = listType === ListType.Task;
  const isBullet = listType === ListType.Bulleted;
  const isNumbered = listType === ListType.Numbered;
  const InnerList = isOrderedList(props.element) ? 'ol' : 'ul';
  const markerStyle =
    isNumbered && listStart === undefined
      ? 'none'
      : (listStyle ?? (isNumbered ? 'decimal' : isBullet ? 'disc' : 'none'));

  return (
    <InnerList
      className="relative m-0 p-0"
      data-list-id={props.element.listId ?? ''}
      data-list-levels={
        props.element.listLevels
          ? JSON.stringify(props.element.listLevels)
          : undefined
      }
      style={{ listStyleType: markerStyle }}
      start={isNumbered ? listStart : undefined}
    >
      <li
        data-checked={
          isTask ? String(props.element.checked === true) : undefined
        }
        data-indent={props.element.indent}
        data-list-id={props.element.listId ?? ''}
        data-list-levels={
          props.element.listLevels
            ? JSON.stringify(props.element.listLevels)
            : undefined
        }
        data-list-restart={props.element.listRestart}
        data-list-start={props.element.listStart}
        data-list-style={isBullet ? listStyle : undefined}
        data-list-type={listType}
        className={
          isTask
            ? cn(
                'list-none',
                props.element.checked === true &&
                  'text-muted-foreground line-through'
              )
            : undefined
        }
      >
        {isTask && <TodoMarkerStatic {...props} />}
        {props.children}
      </li>
    </InnerList>
  );
}

function TodoMarkerStatic(
  props: Parameters<NonNullable<ReturnType<ListWrapper>>>[0] & {
    listStart?: number;
    listStyle?: string;
    listType: ListType;
  }
) {
  const checked = props.element.checked === true;

  return (
    <button
      className={cn(
        'bg-input/90 data-checked:bg-primary data-checked:text-primary-foreground dark:data-checked:bg-primary data-checked:border-primary border-transparent aria-invalid:aria-checked:border-primary aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 flex size-4 items-center justify-center rounded-[5px] border transition-shadow group-has-disabled/field:opacity-50 focus-visible:ring-3 aria-invalid:ring-3 group-has-[:focus-visible]/field-label:ring-0 group-has-[:focus-visible]/field-label:not-data-checked:border-transparent group-has-[:focus-visible]/field-label:data-checked:border-primary peer -start-6 pointer-events-none absolute top-1 shrink-0',
        props.className
      )}
      data-checked={checked || undefined}
      data-state={checked ? 'checked' : 'unchecked'}
      type="button"
    >
      <div className="[&>svg]:size-3.5 grid place-content-center text-current">
        {checked && (
          <svg
            aria-hidden="true"
            className="size-3.5"
            fill="none"
            stroke="currentColor"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            viewBox="0 0 24 24"
          >
            <path d="M20 6 9 17l-5-5" />
          </svg>
        )}
      </div>
    </button>
  );
}
